INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('a797157d-0bb5-4924-886d-14384c9d4068', '78af4a18-5f12-412a-b815-c7cc6931356a', 'Ana e Bruno, com qualificações equivalentes, foram aprovados e nomeados em um concurso público. Na distribuição de funções, o chefe de departamento, que possuía uma amizade de longa data com Bruno, decidiu alocá-lo em um projeto de alta visibilidade e maior prestígio. Ana, apesar de suas qualificações semelhantes, foi direcionada para um setor de rotina, sem o mesmo destaque ou oportunidade de desenvolvimento. Diante desse contexto, qual foi o princípio da Administração Pública violado pela decisão do chefe de departamento?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Serviço Intermunicipal de Água e Esgoto SIMAE - SC / Agente de Obras / Questão: 23', 'A resposta correta é a "d". O princípio da impessoalidade, previsto no art. 37, caput, da CF/1988, exige que a Administração trate seus agentes e administrados sem favorecimentos pessoais, pautando suas decisões exclusivamente pelo interesse público. Ao beneficiar Bruno em razão de amizade pessoal, o chefe de departamento agiu de forma pessoalizada e discriminatória, violando diretamente esse princípio. As demais alternativas descrevem outros conceitos que não se ajustam com precisão à situação descrita.', 1, true),
('1af0ded7-0996-4da8-b78a-0aa21bbbf670', '78af4a18-5f12-412a-b815-c7cc6931356a', 'O art. 37, §6º, da Constituição Federal de 1988 (CF 88), dispõe que as pessoas jurídicas de direito público e as de direito privado prestadoras de serviços públicos responderão pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa, ele está se referindo à:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Santa Rosa - RS / Agente de Controle Interno / Questão: 31', 'A resposta correta é a "e". O art. 37, §6º, da CF/1988 consagra a responsabilidade civil objetiva do Estado, fundamentada na teoria do risco administrativo: basta a comprovação da conduta do agente público (nessa qualidade), do dano e do nexo causal entre eles, sendo dispensada a comprovação de dolo ou culpa da Administração — esta somente é exigida para o exercício do direito de regresso contra o agente causador do dano. As demais alternativas descrevem elementos da responsabilidade subjetiva ou institutos estranhos ao dispositivo.', 2, true),
('e30358f9-411a-4df2-a54d-3622662594c0', '78af4a18-5f12-412a-b815-c7cc6931356a', 'De acordo com a Constituição Federal, são princípios da Administração pública, EXCETO:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2024 / Prefeitura de Alpestre - RS / Borracheiro / Questão: 18', 'A resposta correta é a "c", pois "subordinação" não é um dos princípios expressos no art. 37, caput, da CF/1988, que elenca apenas legalidade, impessoalidade, moralidade, publicidade e eficiência.', 3, true),
('85a917f4-ac16-4f2a-addc-a24276dd2e9a', '78af4a18-5f12-412a-b815-c7cc6931356a', 'Quanto à acumulação de cargos públicos, cargos e proventos, assinale a alternativa correta.', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2022 / Prefeitura de Erechim - RS / Procurador do Município / Questão: 58', 'A resposta correta é a "e", pois o art. 37, XVI, da CF/1988, ao vedar a acumulação remunerada de cargos, aplica-se apenas a cargos efetivos, sendo o cargo em comissão passível de ser exercido por servidor já aposentado, sem violação à regra geral de vedação de acúmulo. As demais alternativas estão incorretas: a acumulação de profissionais de saúde limita-se a "dois" cargos, não três ("a"); as exceções constitucionais são taxativas, e não exemplificativas ("b"); e a acumulação exige, sim, compatibilidade de horários, e não sua ausência ("d").', 4, true),
('01c1443e-3229-4268-9742-c6de096f330d', '78af4a18-5f12-412a-b815-c7cc6931356a', 'Um servidor público é nomeado para um cargo de comissão sem ter sido aprovado em concurso público. De acordo com a Constituição Federal, essa nomeação é', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2026 / Prefeitura Municipal de Sarandi/RS - RS / Médico / Questão: 30', 'A resposta correta é a "c", conforme o art. 37, II, da CF/1988, que ressalva expressamente as nomeações para cargo em comissão declarado em lei de livre nomeação e exoneração da exigência de aprovação prévia em concurso público.', 5, true),
('a025d772-fa28-4cec-9e3d-5c582a4f4fa9', '78af4a18-5f12-412a-b815-c7cc6931356a', 'Conforme o que estabelece o art. 40 da CF/88, o regime próprio de previdência social dos servidores titulares de cargos efetivos terá caráter contributivo e solidário, mediante contribuição do respectivo ente federativo, de servidores ativos, de aposentados e de pensionistas, observados critérios que preservem o equilíbrio financeiro e atuarial. Nesse sentido, o servidor abrangido por regime próprio de previdência social será aposentado: I. Por incapacidade permanente para o trabalho, no cargo em que estiver investido, quando insuscetível de readaptação, hipótese em que será obrigatória a realização de avaliações periódicas para verificação da continuidade das condições que ensejaram a concessão da aposentadoria, na forma da lei do respectivo ente federativo.II. Compulsoriamente, aos 65 anos de idade, com proventos proporcionais ao tempo de contribuição.III. Voluntariamente, desde que cumprido tempo mínimo de 10 anos de efetivo exercício no serviço público e 5 anos no cargo efetivo em que se dará a aposentadoria, observados 60 anos de idade e 35 de contribuição, se homem, e 55 anos de idade e 30 de contribuição, se mulher, e 65 anos de idade, se homem, e 60 anos de idade, se mulher, com proventos proporcionais ao tempo de contribuição. Quais estão corretas?', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Instituto de Previdência dos Servidores Públicos de Santa Rosa PREVIROSA - RS / Procurador Jurídico / Questão: 60', 'A resposta correta é a "a". O item I reproduz corretamente o art. 40, §1º, I. O item II está errado, pois a aposentadoria compulsória se dá aos 70 ou 75 anos, e não 65 (art. 40, §1º, II). O item III traz uma mistura incorreta de idades e tempos de contribuição que não correspondem à regra atual (pós-EC 103/2019) de aposentadoria voluntária.', 6, true),
('5dda054d-67c9-455f-ad51-dca48071b6a1', '78af4a18-5f12-412a-b815-c7cc6931356a', 'A estabilidade do servidor público está prevista na Constituição Federal. Considere que Ana, após ser nomeada, tomou posse em cargo público em 01/03/2019 e, na mesma data, entrou em exercício, sendo que, de lá para cá, não houve interrupção do exercício da atividade profissional. Além disso, Ana obteve êxito nas avaliações de desempenho realizadas no período de estágio probatório. Considerando o caso hipotético apresentado, é correto afirmar que Ana será estável no cargo a partir de:', 'Fundação Universidade Empresa de Tecnologia e Ciências- FUNDATEC 2025 / Prefeitura de Três de Maio - RS / Engenheiro Civil / Questão: 25', 'A resposta correta é a "c". O art. 41, caput, da CF/1988 exige três anos de efetivo exercício para a aquisição da estabilidade. Como Ana entrou em exercício em 01/03/2019, sem interrupções, sua estabilidade se completa em 01/03/2022.', 7, true);
