('1af0ded7-0996-4da8-b78a-0aa21bbbf670', 'D', 'Necessidade de conduta e dano, apenas às terras devolutas indispensáveis à defesa das fronteiras.', false, 3),
('1af0ded7-0996-4da8-b78a-0aa21bbbf670', 'E', 'Teoria do risco administrativo.', true, 4),
('e30358f9-411a-4df2-a54d-3622662594c0', 'A', 'Publicidade.', false, 0),
