('e30358f9-411a-4df2-a54d-3622662594c0', 'C', 'Subordinação.', true, 2),
('e30358f9-411a-4df2-a54d-3622662594c0', 'D', 'Moralidade.', false, 3),
('e30358f9-411a-4df2-a54d-3622662594c0', 'E', 'Eficiência.', false, 4),
('85a917f4-ac16-4f2a-addc-a24276dd2e9a', 'A', 'A acumulação remunerada de cargos públicos, com previsão na Constituição Federal, autoriza a acumulação remunerada de três cargos de enfermeiros.', false, 0),
('85a917f4-ac16-4f2a-addc-a24276dd2e9a', 'B', 'A constituição federal estabelece como regra a impossibilidade de acumulação de cargos públicos remunerados. No entanto, estabelece algumas exceções. Estas exceções previstas no seu texto são exemplificativas.', false, 1),
('85a917f4-ac16-4f2a-addc-a24276dd2e9a', 'C', 'O magistrado, mesmo que esteja em disponibilidade, não pode acumular cargo público.', false, 2),
('85a917f4-ac16-4f2a-addc-a24276dd2e9a', 'D', 'A acumulação de cargos públicos, prevista na Constituição Federal, leva em consideração a possibilidade de acúmulo, desde que não haja compatibilidade de horário.', false, 3),
('85a917f4-ac16-4f2a-addc-a24276dd2e9a', 'E', 'É possível que um servidor aposentado seja nomeado para cargo em comissão, por expressa previsão constitucional.', true, 4),
('01c1443e-3229-4268-9742-c6de096f330d', 'A', 'proibida, pois todos os cargos públicos exigem aprovação em concurso público.', false, 0),
('01c1443e-3229-4268-9742-c6de096f330d', 'B', 'permitida apenas se o servidor já tiver sido aprovado em concurso público anteriormente.', false, 1),
('01c1443e-3229-4268-9742-c6de096f330d', 'C', 'permitida, desde que o cargo seja de provimento em comissão, declarado em lei de livre nomeação e exoneração.', true, 2),
('01c1443e-3229-4268-9742-c6de096f330d', 'D', 'permitida, desde que o servidor seja aprovado em concurso público no prazo de 1 ano.', false, 3),
('a025d772-fa28-4cec-9e3d-5c582a4f4fa9', 'A', 'Apenas I.', true, 0),
('a025d772-fa28-4cec-9e3d-5c582a4f4fa9', 'B', 'Apenas II.', false, 1),
('a025d772-fa28-4cec-9e3d-5c582a4f4fa9', 'C', 'Apenas I e II.', false, 2),
